function editProduct(pid,artistMode=false){uploadId=null;const p=pid?productById(pid):null;if(artistMode){openModal(t('Edit your listing'),artistListingForm(p));return;}const example=p||seed.products[0];openModal(artistMode?t('Edit your listing'):p?t('Edit product'):t('Add a product'),`<form data-form="${artistMode?'artist-edit':'admin-product'}">${p?`<input type="hidden" name="id" value="${esc(p.id)}">`:''}${p?.upload_id?`<input type="hidden" name="upload_id" value="${esc(p.upload_id)}">`:''}${designArtworkUpload(p)}${designPlacementPreview(p||{category:cats[0]})}<div class="form-grid">${field(t('Title (English)'),'title',p?.title||'','text','required maxlength="100" dir="ltr" lang="en"')+field(t('Title (Arabic)'),'title_ar',p?.title_ar||'','text','maxlength="100" dir="rtl" lang="ar"')}<label class="field">${t("Category")}<select name="category">${cats.map(c=>`<option value="${esc(c)}" ${p?.category===c?'selected':''}>${t(c)}</option>`).join('')}</select></label>${field(t('Price (SAR)'),'price',(p?.price??9900)/100,'number','required min="0" max="1000" step="0.01"')}${field(t('Quantity'),'stock',p?.stock??50,'number','required min="0" max="100000"')}${artistMode?'':`<label class="field">${t("Artist")}<select name="artist_id">${artists.map(a=>`<option value="${esc(a.id)}" ${a.id===p?.artist_id?'selected':''}>${esc(localField(a,'name'))}</option>`).join('')}</select></label><label class="field">${t("Status")}<select name="status">${['active','pending','changes_requested','archived'].map(s=>`<option value="${esc(s)}" ${p?.status===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></label>`}${field(t('Options (comma separated)'),'variants',p?.variants?.join(', ')||'Standard','text','required maxlength="300"',true)}<label class="field full">${t("Description")}<textarea name="description" required maxlength="2000" dir="ltr" lang="en">${esc(p?.description||'An original design for your everyday.')}</textarea></label>${!p?.upload_id&&!artistMode?`<label class="field full">${t("Catalog image")}<select name="image_index">${seed.products.map((x,i)=>`<option value="${i}" ${x.sheet===example.sheet&&x.cell===example.cell?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label>`:''}</div>${customerCustomizationField(p)}${bilingualListingExtras(p)}${productDetailsFields(p||{})}${!artistMode?field(t('Administrator feedback'),'review_feedback',p?.review?.feedback||'','text','maxlength="2000"',true):''}${artistMode?`<p class="small">${t("Changes return the listing to pending review.")}</p>`:''}<button class="btn full" type="submit">${artistMode?t('Resubmit for review'):t('Save product')}</button></form>`);}
function manageOrder(oid){const o=viewData?.orders.find(o=>o.id===oid);if(!o)return;const states={awaiting_payment:['awaiting_payment','cancelled'],new:mode==='demo'?['new','processing','cancelled']:['new','cancelled'],processing:['processing','shipped','cancelled'],shipped:['shipped','delivered'],delivered:['delivered'],cancelled:['cancelled']};openModal(t('Manage order'),`<p><strong>${esc(o.id)}</strong><br>${esc(o.customer.name)} · ${esc(o.customer.email)}<br>${esc(o.customer.address)}, ${esc(o.customer.city)}, ${esc(o.customer.postal||'')} · ${esc(o.customer.country||'')}<br>${esc(o.customer.phone)}</p><div class="notice demo">${money(o.total)} · ${esc(statusLabel(o.payment_status))}</div>${o.items.map(p=>productionLineCard(o,p)).join('')}${productionOrderPanel(o)}${mode==='server'&&['awaiting_payment','new'].includes(o.status)?`<form data-form="admin-record-payment" class="panel bottom-gap"><input type="hidden" name="id" value="${esc(o.id)}"><h3>${t("Record a test external payment")}</h3><p class="small">${t("Staging simulation only. This action does not charge the customer or trigger a transfer.")}</p>${field(t('Payment reference'),'reference','','text','required maxlength="150"')}<button class="btn full">${t("Record test payment")}</button></form>`:''}<form data-form="admin-order"><input type="hidden" name="id" value="${esc(o.id)}"><label class="field">${t("Status")}<select name="status">${states[o.status].map(s=>`<option value="${esc(s)}">${statusLabel(s)}</option>`).join('')}</select></label>${field(t('Tracking reference'),'tracking',o.tracking||'','text','maxlength="100"')}<button class="btn full" type="submit">${t("Update order")}</button></form>`);}
