function syncState(){if(mode!=='server'||!user)return;const snapshot={cart:clone(cart),saved:clone(saved)};stateQueue=stateQueue.then(()=>api('state',snapshot)).catch(e=>toast(t('Account sync failed: {error}',{error:localizedError(e.message)})));}
async function loadState(merge=false){if(mode!=='server'||!user)return;const state=await api('state');const localCart=cart,localSaved=saved;cart=state.cart||[];saved=state.saved||[];addressBook=state.address||{};if(merge){for(const l of localCart)if(products.some(p=>p.id===l.id)&&!cart.some(p=>p.key===l.key))cart.push(l);saved=[...new Set([...saved,...localSaved])];}write('cart',cart);write('saved',saved);if(merge){syncState();await stateQueue;}}
function storeCart(){write('cart',cart);syncState();}

function addToBag(pid,variant){const p=products.find(p=>p.id===pid);if(!p)throw Error('This product is unavailable.');if(!p.variants.includes(variant))throw Error('Choose a valid option.');const key=pid+'::'+variant,existing=cart.find(l=>l.key===key),total=cart.filter(l=>l.id===pid).reduce((n,l)=>n+l.qty,0);if(total>=p.stock||(existing?.qty||0)>=20)throw Error('You’ve reached the available quantity.');if(existing)existing.qty++;else cart.push({key,id:pid,variant,qty:1});storeCart();openModal(t('A very good choice.'),`${photo(p)}<h3 style="text-align:center;margin-bottom:10px">${esc(localField(p,'title'))}</h3><p style="text-align:center">${t("Added to your bag.")} ${esc(variant)} · ${money(p.price)}</p><div class="stack">${link(t('View bag & checkout')+' '+icon('arrow'),'bag','btn full')}${button(t('Keep exploring'),'close-modal','','btn outline full')}</div>`);render();}
