 if(action==='logout'){await flushCustomerDraft().catch(()=>{});clearTimeout(customerSaveTimer);await stateQueue;await api('logout',{});user=null;customerDraft=null;cart=[];saved=[];addressBook={};lastOrder=null;write('cart',[]);write('saved',[]);write('last-order',null);go('home');return}
