let appReady=false;
async function boot(attempt=0){
 if(window.VEELAD_DEMO===true){mode='demo';dbLocal=dbLocal||initialDemo();persist();const uid=read('demo-user',null);user=dbLocal.users.find(u=>u.id===uid&&u.status==='active')||null;}
 else {mode='server';dbLocal=null;try{const res=await fetch('/api.php?route=bootstrap',{credentials:'same-origin',signal:AbortSignal.timeout(10000)});const b=await res.json();if(res.status===503&&b.database_error==='SCHEMA_INITIALIZING'&&attempt<15){$('#app').innerHTML=`<main class="center-page"><h1>${t("Opening the store…")}</h1><p>${t("Please wait a moment.")}</p></main>`;setTimeout(()=>boot(attempt+1),2000);return;}if(!res.ok||b.mode!=='server'||!Array.isArray(b.products))throw Error('Store unavailable');csrf=b.csrf;user=b.user;products=b.products;artists=b.artists;settings=b.settings;emailDelivery=b.email_delivery||{available:false};authentication=b.authentication||{google:{available:false},has_password:true};if(user)await loadState(b.auth_event==='google-login');}catch(e){$('#app').innerHTML=`<main class="center-page"><h1>${t("We’ll be right back.")}</h1><p>${t("The store cannot connect right now. Please try again shortly.")}</p><button class="btn" data-action="retry-store">${t("Try again")}</button></main>`;return;}}
 appReady=true;await render();
}
boot();
